REF:
PANEL.STUDY */
.estudo-atividade-card {
  display: flex;
  flex: 0 0 100px;
  flex-direction: column;
  gap: 20px;
  width: 99%;
  align-self: center;
  padding: 0 5px 3px;

  border: 1px solid transparent;
  border-radius: 12px;

  background: transparent;
  box-shadow: none;

  box-sizing: border-box;
}

/* CABEÇALHO DE CADA CARTÃO */
/* ID: CSS-180

PANEL.STUDY.GOALS */
/* ACABAMENTO IGUAL AO BOTÃO COMPROVANTES */

/* ESTADO NORMAL */
.card-central.card-estudo .estudo-botao-metas {
  background:
    /* Reflexo diagonal */
    linear-gradient(
      225deg,
      rgba(255, 255, 255, 0.012) 0%,
      rgba(255, 255, 255, 0.005) 14%,
      transparent 32%,
      transparent 48%,
      rgba(0, 25, 8, 0.01) 76%,
      rgba(0, 20, 5, 0.025) 100%
    ),

    /* Reflexo verde à esquerda */
    radial-gradient(
      ellipse 65% 110% at 5% 0%,
      rgba(115, 255, 155, 0.045) 0%,
      rgba(45, 215, 85, 0.015) 45%,
      transparent 78%
    ),

    /* Reflexo verde à direita */
    radial-gradient(
      ellipse 52% 120% at 100% 0%,
      rgba(95, 255, 130, 0.04) 0%,
      rgba(35, 190, 70, 0.012) 48%,
      transparent 82%
    ),

    /* Brilho superior */
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.006) 0%,
      transparent 55%
    ),

    /* Base verde */
    linear-gradient(
      110deg,
      rgba(6, 71, 25, 0.38) 0%,
      rgba(7, 91, 33, 0.38) 35%,
      rgba(11, 125, 43, 0.38) 68%,
      rgba(27, 162, 71, 0.38) 100%
    );

  border: 1px solid rgba(106, 245, 151, .75);
  border-radius: 12px;
  color: #ffffff;

  box-shadow:
    inset 2px 2px 4px rgba(255, 255, 255, .28),
    inset -3px -4px 7px rgba(0, 35, 15, .35),
    4px 6px 12px rgba(0, 75, 35, .25),
    0 0 7px rgba(43, 219, 103, .16);

  isolation: isolate;

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    filter .2s ease;
}

/* HOVER */
.card-central.card-estudo .estudo-botao-metas:hover {
  transform: translateY(23px);
  filter: brightness(1.07);

  box-shadow:
    inset 2px 2px 4px rgba(255, 255, 255, .32),
    inset -3px -4px 7px rgba(0, 35, 15, .30),
    5px 8px 14px rgba(0, 75, 35, .30),
    0 0 12px rgba(43, 219, 103, .28);
}

/* ACTIVE */
.card-central.card-estudo .estudo-botao-metas:active {
  transform: translateY(26px);

  box-shadow:
    inset 5px 5px 10px rgba(0, 45, 20, .35),
    inset -3px -3px 7px rgba(110, 255, 160, .16),
    0 2px 4px rgba(0, 50, 20, .18);
}

/* EFEITO AO PASSAR O MOUSE */
.card-central.card-estudo .estudo-botao-metas:hover {
  transform: translateY(23px);
  filter: brightness(1.07);

  box-shadow:
    inset 2px 2px 4px rgba(255,255,255,.32),
    inset -3px -4px 7px rgba(0,35,15,.30),
    5px 8px 14px rgba(0,75,35,.30),
    0 0 12px rgba(43,219,103,.28);
}

/* EFEITO AO CLICAR */
.card-central.card-estudo .estudo-botao-metas:active {
  transform: translateY(26px);

  box-shadow:
    inset 5px 5px 10px rgba(0,45,20,.35),
    inset -3px -3px 7px rgba(110,255,160,.16),
    0 2px 4px rgba(0,50,20,.18);
}


/* ID: CSS-318

PANEL.ROUTINE.WEEKLY.TITLE */

#card-rotina-semanal {
  position: relative;
}

#card-rotina-semanal > .rotina-card-cabecalho {
  min-height: 1px;
}

/* TÍTULO SEMANAL — BORDA VERDE SUTIL */
#card-rotina-semanal .rotina-card-cabecalho h3.estudo-campo-rotulo {
  font-weight: 600;
  border: 1px solid rgba(126, 214, 103, .45) !important;
  border-radius: 3px;
}

