========================================================= */

/* ID: DARK-166

PANEL.ROUTINE.AGENDA.NEUMORPHISM */
/* NEUMORFISMO EXTERNO E INTERNO — ONTEM E HOJE */

#card-agenda-ontem,
#card-agenda-hoje {
  box-shadow:

    /* SOMBRA EXTERNA INFERIOR E DIREITA */
    6px 7px 12px rgba(0, 0, 0, .65),

    /* ILUMINAÇÃO EXTERNA SUPERIOR E ESQUERDA */
    -5px -5px 11px rgba(75, 115, 86, .16),

    /* ILUMINAÇÃO INTERNA SUPERIOR E ESQUERDA */
    inset 1px 1px 3px rgba(195, 255, 215, .08),

    /* PROFUNDIDADE INTERNA INFERIOR E DIREITA */
    inset -2px -2px 4px rgba(0, 0, 0, .42) !important;
}

/* ID: DARK-187

PANEL.ROUTINE.PENDING.CONTENT.INSET.LEFT */
/* LIMITE INTERNO FIXO À ESQUERDA; BASE PARA O FUTURO BOTÃO */
