  flex: 0 0 6px !important;
  height: 6px !important;
  transform: translateY(3px) !important;
}

/* ID: DARK-191

PANEL.ROUTINE.PENDING.LIST.CONTAINER.RADIUS */
#card-rotina-pendente #lista-pendencias-rotina {
  border-radius: 6px !important;

}

/* Regras nativas aposentadas: trilho independente no HTML e JS-007. */

