PANEL.ROUTINE.AGENDA.ROW.ACTIVITY.WIDTH */
/* RESERVA O DESLOCAMENTO DO TÍTULO NO CÁLCULO REAL DA LINHA */

#card-agenda-ontem .rotina-item-horario .rotina-atividade,
#card-agenda-hoje .rotina-item-horario .rotina-atividade {
  transform: none !important;
  margin-left: 25px !important;
}

/* ID: DARK-195

PANEL.ROUTINE.AGENDA.SCROLLBAR.GAP */
/* ESPAÇO ENTRE A LISTA E A BARRA HORIZONTAL */

#card-agenda-ontem #barra-agenda-ontem,
#card-agenda-hoje #barra-agenda-hoje {
  margin-top: 8px !important;
  margin-bottom: 0 !important;
}

/* ============================================================
   ID: DARK-0198

PANEL.COMMITMENT.EVENT.CARDS.LIGHTER
   DIMENSÕES E APARÊNCIA DOS CARDS — ONTEM E HOJE */

#painel-compromisso #lista-compromissos-ontem > .compromisso-evento,
#painel-compromisso #lista-compromissos-hoje > .compromisso-evento {

    gap: 5px;
    padding: 6px 9px;

    background: linear-gradient(
        145deg,
        #1b3323,
        #13271b
    );
}

/* TÍTULO E ÍCONE DO EVENTO */
#painel-compromisso .compromisso-evento-cabecalho {
  display: flex;
  align-items: center;
  gap: 7px;

  min-width: 0;

}

#painel-compromisso .compromisso-documento {
  flex: 0 0 auto;
  color: #55e58e;
  font-size: 20px;
  line-height: 1;
}

#painel-compromisso .compromisso-evento-cabecalho h4 {
  flex: 1;
  min-width: 0;

  margin: 0;

  color: #eaf5ed;
  font-size: 13px;
  font-weight: 800;

  white-space: nowrap;
}

#painel-compromisso .compromisso-evento-cabecalho h4 strong {
  color: #39d879;
}

#painel-compromisso .compromisso-fixar {
  flex: 0 0 auto;
  color: #54df8b;
  font-size: 17px;
}

/* POSICIONAMENTO DA LIXEIRA — PENDENTES */
#painel-compromisso #lista-compromissos-pendentes
.compromisso-evento-cabecalho > .compromisso-fixar {
  position: absolute;
  top: -10px;
  right: -4px;
}

/* LOCAL, DATA E HORÁRIO */
#painel-compromisso .compromisso-evento-dados {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1.2fr)
    minmax(0, .85fr);

  gap: 5px;
  min-width: 0;
}

#painel-compromisso .compromisso-evento-dado {
  display: flex;
  flex-direction: column;
  gap: 0;

  position: relative;
  min-width: 0;
  padding: 8px 3px 4px;
  box-sizing: border-box;

  border: 1px solid rgba(80, 220, 115, .65);
  border-radius: 6px;

  background: linear-gradient(
    145deg,
    #102319,
    #09140e
  );
}

/* ID: DARK-198

PANEL.COMMITMENT.HEADER.ALIGNMENT */
/* ALINHAMENTO DO ÍCONE COM O CABEÇALHO DA ROTINA */

#painel-compromisso .compromisso-cabecalho {
  position: relative !important;
  top: -3px !important;

  flex: 0 0 34px !important;
  height: 34px !important;
  min-height: 34px !important;

  padding: 0 !important;
}


/* DESENHO INTERNO — LUMINOSIDADE CONTROLADA */
#painel-compromisso .compromisso-icone svg {
    display: block;

    filter:
        brightness(1.12)
        drop-shadow(0 1px 1px rgba(0, 20, 10, .42))
        drop-shadow(0 0 2px rgba(190, 255, 207, .24));
}


/* POSIÇÃO HORIZONTAL */
#painel-compromisso .compromisso-identificacao {
  gap: 6px !important;
  transform: translateX(-3px) !important;
}

/* ID: DARK-200

PANEL.ROUTINE.PERIODS.ARROWS */
/* REMOVE AS SETAS DOS BOTÕES DE PERÍODO */

#painel-rotina .rotina-periodo-card {
  grid-template-columns: 30px minmax(0, 1fr) !important;
}

#painel-rotina .rotina-periodo-seta {
  display: none !important;
}

/* ID: DARK-202

PANEL.COMMITMENT.CATEGORY.CALENDAR_ICON */
/* REUTILIZAÇÃO DO ÍCONE CRIAR PLANO */

#painel-compromisso .compromisso-categoria-icone {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 25px;
  height: 22px;
  color: #b9ffd0;
}

/* ID: DARK-204

PANEL.COMMITMENT.CATEGORY.URGENT.PIN */
/* CORREÇÃO DE COR E ENQUADRAMENTO DO ALFINETE */

#painel-compromisso .compromisso-categoria-urgente > span:first-child {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 25px !important;
  height: 22px !important;
  color: #ff505a !important;
}

#painel-compromisso .compromisso-urgente-icone {
  display: block !important;
  width: 17px !important;
  height: 17px !important;
  flex: 0 0 17px !important;
  color: #ff505a !important;
  transform: translateY(-1px) !important;
}

#painel-compromisso .compromisso-urgente-icone * {
  stroke: #ff505a !important;
}

/* ID: DARK-206

PANEL.COMMITMENT.PENDING.LABEL + PANEL.REMINDER.SUMMARY.LABEL */
/* RÓTULO VERMELHO — PADRÃO COMPARTILHADO */

#painel-compromisso .compromisso-pendencias-rotulo,
#painel-lembrete #card-lembrete-pendencias .compromisso-pendencias-rotulo {
  background: #1b1012 !important;
  border-color: rgba(255, 120, 130, .75) !important;
  color: #ff858c !important;
  z-index: 2;
}

/* REGRA LEGADA APOSENTADA: SEM SELETOR ATIVO. */
/* REGRA LEGADA DO CURSOR VERMELHO SUBSTITUÍDA PELO TRILHO INDEPENDENTE. */


/* ID: DARK-208

COMPONENT.SCROLLBAR.VERTICAL.FINANCIAL.OVERDUE */
.ci-scrollbar-financeiro .ci-scrollbar-trilho,
.ci-scrollbar-rotina-pendencias .ci-scrollbar-trilho,
.ci-scrollbar-compromisso-pendentes .ci-scrollbar-trilho {
  border-color: rgba(225,80,94,.48);
  box-shadow: inset 2px 2px 4px rgba(0,0,0,.65), inset -1px -1px 3px rgba(210,60,75,.16);
}

/* TRILHO FINANCEIRO — FUNDO VERMELHO-GRAFITE */
.ci-scrollbar-financeiro .ci-scrollbar-trilho {
  background: linear-gradient(
    145deg,
    #241519,
    #160d11
  ) !important;
}

.ci-scrollbar-financeiro .ci-scrollbar-cursor,
.ci-scrollbar-rotina-pendencias .ci-scrollbar-cursor,
.ci-scrollbar-compromisso-pendentes .ci-scrollbar-cursor {
  background: linear-gradient(180deg,#ff9ba2,#ed3545,#a90d1b);
  border-color: rgba(255,205,210,.40);
  box-shadow: 0 0 6px rgba(229,9,20,.32);
}

/* ID: DARK-211

PANEL.COMMITMENT.PENDING.ICON.TRASH */
/* BOTÃO CIRCULAR — ACABAMENTO METÁLICO */

#painel-compromisso .compromisso-lixeira-icone {
  display: inline-flex;
  flex: 0 0 24px;
  width: 24px;
  height: 24px;

  align-items: center;
  justify-content: center;

  box-sizing: border-box;
  border: 1px solid rgba(255, 170, 176, .95);
  border-radius: 50%;

  background: radial-gradient(
    circle at 30% 22%,
    #91434d 0%,
    #672933 42%,
    #35151c 100%
  );

  box-shadow:
    0 0 0 2px rgba(255, 75, 95, .13),
    0 3px 6px rgba(0, 0, 0, .75),
    0 0 9px rgba(255, 75, 95, .32),
    inset 0 1px 2px rgba(255, 255, 255, .35),
    inset 0 -3px 4px rgba(0, 0, 0, .55);

  color: #ff858c;
}

#painel-compromisso #lista-compromissos-pendentes
.compromisso-documento,
#painel-compromisso #lista-compromissos-pendentes
.compromisso-lixeira-icone {

  color: #ff858c;
}

/* ID: DARK-215

PANEL.COMMITMENT.PENDING.HIDE_NATIVE_SCROLLBAR */

/* OCULTA A BARRA NATIVA, PRESERVANDO A ROLAGEM */
#painel-compromisso #lista-compromissos-pendentes {
  overflow-y: auto !important;
  overflow-x: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

#painel-compromisso #lista-compromissos-pendentes::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* ID: DARK-217

PANEL.COMMITMENT.PENDING.SCROLLBAR.OFFSET */
/* MANTÉM A BARRA NA POSIÇÃO ORIGINAL */
#painel-compromisso #barra-vertical-compromisso-pendentes {
  transform: translateX(-4px);
}


/* =========================================================
   ID: DARK-0222

PANEL.COMMITMENT.LISTS.ICONS.COLORS
   CORES DOS ÍCONES — ONTEM E HOJE */

/* ÍCONES PRINCIPAIS — VERDE, EXCETO O ALFINETE */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento-cabecalho > svg,

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento-cabecalho > svg {
    color: #39d879 !important;
    filter: none !important;
}

/* ALFINETE ORIGINAL — BRANCO */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento-cabecalho svg[viewBox="-4 -18 279 281"],

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento-cabecalho svg[viewBox="-4 -18 279 281"] {
    color: #ffffff !important;
    stroke: currentColor !important;
    filter: none !important;
}

/* PENDENTES — VERMELHO */
#painel-compromisso #lista-compromissos-pendentes
.compromisso-evento-cabecalho > svg {
    color: #ff858c !important;

    filter:
        drop-shadow(0 2px 3px rgba(0, 0, 0, .75))
        drop-shadow(0 0 5px rgba(255, 133, 140, .40)) !important;
}

/* ID: DARK-220

PANEL.COMMITMENT.EVENT.ICON.NEUMORPHIC
   ACABAMENTO VERDE E POSICIONAMENTO DOS QUATRO ÍCONES */

#painel-compromisso #lista-compromissos-ontem
.compromisso-evento-cabecalho > svg:not(.estudo-atividade-alfinete):not([viewBox="-4 -18 279 281"]),

#painel-compromisso #lista-compromissos-hoje
