    display: block !important;
    flex: 0 0 28px !important;
    width: 28px !important;
    height: 28px !important;
    padding: 3px !important;
    box-sizing: border-box !important;
    border-radius: 50% !important;
    color: #ffffff !important;

    background: linear-gradient(
        145deg,
        #25bd70 0%,
        #087b3e 55%,
        #034d29 100%
    ) !important;

    /* APROXIMAÇÃO DAS BORDAS */
    position: relative !important;
    left: -5px !important;
    top: -5px !important;

    /* SEM SOMBRA OU REFLEXO */
    box-shadow: none !important;
}

/* ALFINETE ORIGINAL — SEM FUNDO */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento-cabecalho > svg.estudo-atividade-alfinete,

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento-cabecalho > svg.estudo-atividade-alfinete {
    background: none !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 0 !important;
    filter: none !important;
    color: #b9c8bd !important;
}

