/* ID: DARK-230

PANEL.COMMITMENT.EVENT.FIELDS.GRID */
/* PADRONIZAÇÃO DOS QUATRO CARTÕES — ONTEM E HOJE */

/* GRADE DOS CAMPOS */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento .compromisso-evento-dados,

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento .compromisso-evento-dados {

    display: grid !important;

    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

    grid-template-areas:
        "local local"
        "data horario";

    column-gap: 8px;
    row-gap: 10px;

    align-items: stretch;
}

/* BASE DOS TRÊS CAMPOS */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado,

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado {

    position: relative;

    min-width: 0;
    margin: 0;

    box-sizing: border-box;
}

/* LOCAL — PRIMEIRA LINHA CENTRALIZADA */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:first-child,

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:first-child {

    grid-area: local;

    width: 106px;
    max-width: 100%;

    justify-self: center;

    left: auto;
    top: auto;
    transform: none;
}

/* DATA — SEGUNDA LINHA ESQUERDA */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:nth-child(2),

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:nth-child(2) {

    grid-area: data;

    width: auto;
    min-width: 0;
}

/* HORÁRIO — SEGUNDA LINHA DIREITA */
#painel-compromisso #lista-compromissos-ontem
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:nth-child(3),

#painel-compromisso #lista-compromissos-hoje
.compromisso-evento .compromisso-evento-dados
> .compromisso-evento-dado:nth-child(3) {

    grid-area: horario;

    width: auto;
    min-width: 0;
}

/* LOCAL — CENTRALIZADO NA PRIMEIRA LINHA */
#painel-compromisso #lista-compromissos-hoje
> .compromisso-evento:first-child
.compromisso-evento-dados > .compromisso-evento-dado:first-child {

    grid-area: local;

    width: 106px;
    max-width: 100%;
    justify-self: center;

    left: auto;
    top: auto;
    transform: none;

    margin: 0;
}

/* DATA — SEGUNDA LINHA, ESQUERDA */
#painel-compromisso #lista-compromissos-hoje
> .compromisso-evento:first-child
.compromisso-evento-dados > .compromisso-evento-dado:nth-child(2) {

    grid-area: data;
    width: auto;
    min-width: 0;
    margin: 0;
}

/* HORÁRIO — SEGUNDA LINHA, DIREITA */
#painel-compromisso #lista-compromissos-hoje
> .compromisso-evento:first-child
.compromisso-evento-dados > .compromisso-evento-dado:nth-child(3) {

    grid-area: horario;
    width: auto;
    min-width: 0;
    margin: 0;
}

